window.POETRY_REGISTER("v4-pairs-4-22-0.js",{"poems":[["高宗时瑶（胡楚宾，秋浦〖贵池〗人。善属文，高宗召为右史、兼崇贤直学士，预选与诸儒论禁中，撰《臣轨》等书千余篇。朝廷疑议表疏密使参处，以分宰相权，号北门学士。楚宾为文甚敏，必酒中下笔。高宗每命作时，常以金银杯𣂏酒饮之，文成輙赐焉。其英资豪颖，与李白伦，故当时谣曰：）（《全唐诗》八七八《胡楚宾谣》，以为与晚唐顾云、张乔、殷文圭等为同时人，文字有不同。〖2〗）","无名氏","唐","唐诗",53526,"v4-poems-53.js",526],["奉和闲厅晚景司户萨照","赵志","唐","唐诗",57946,"v4-poems-57.js",946]],"pairs":[["玄宗时人","是此谣至早亦应为天宝间李白居秋浦后方可能出现",0,"玄宗時人","是此謠至早亦應爲天寶間李白居秋浦後方可能出現",0],["他对上级","本州的刘长史郑司马极其郑重地冠以敬奉仰等文字",1,"他對上級","本州的劉長史鄭司馬極其鄭重地冠以敬奉仰等文字",0]]});
